draw:
function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);

  // draw buddha
  ctx.lineWidth = 4;
  ctx.strokeStyle = 'black';
  ctx.beginPath();
  ctx.arc(W/2, H/2, 50, 0, 2 * Math.PI);
  ctx.stroke();

  // draw extremes
  ctx.beginPath();
  ctx.arc(W/2 - 100 + 50 * Math.sin(t), H/2, 20, 0, 2 * Math.PI);
  ctx.stroke();
  ctx.beginPath();
  ctx.arc(W/2 + 100 + 50 * Math.sin(t + Math.PI), H/2, 20, 0, 2 * Math.PI);
  ctx.stroke();

  // draw middle path
  ctx.beginPath();
  ctx.moveTo(W/2 - 50, H/2 + 50 * Math.cos(t));
  ctx.lineTo(W/2 + 50, H/2 + 50 * Math.cos(t));
  ctx.stroke();

  ctx.restore();
}
